package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu sync.Mutex
	n  int
}

func (c *Counter) Inc() {
	c.mu.Lock()
	defer c.mu.Unlock() // released on every return path
	c.n++               // protected critical section
}

func main() {
	c := &Counter{} // zero value is ready; pass by pointer
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1) // before launching the goroutine
		go func() {
			defer wg.Done()
			c.Inc()
		}()
	}
	wg.Wait()        // block until all finish
	fmt.Println(c.n) // exactly 100
}
